<?php
/**
 * Plugin Name: NESports Updater V23 (Shop By Color Full Color Fixes)
 * Description: Fixes all color mismatches in Shop by Color (Black, Blue, Gold, Red).
 * Version: 23.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v23_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (strpos($f, 'nesports-pro') === 0) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }
    
    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'assets/images/gym-bag-black-1.jpg' => base64_decode(''),
        'assets/images/gym-bag-black-2.jpg' => base64_decode(''),
        'assets/images/gym-bag-black-3.jpg' => base64_decode(''),
        'assets/images/straps-black-1.jpg' => base64_decode(''),
        'assets/images/straps-black-2.jpg' => base64_decode(''),
        'assets/images/straps-black-3.jpg' => base64_decode(''),
        'assets/images/knee-wrap-blue-1.jpg' => base64_decode(''),
        'assets/images/knee-wrap-blue-2.jpg' => base64_decode(''),
        'assets/images/knee-wrap-blue-3.jpg' => base64_decode(''),
        'assets/images/straps-blue-1.jpg' => base64_decode(''),
        'assets/images/straps-blue-2.jpg' => base64_decode(''),
        'assets/images/straps-blue-3.jpg' => base64_decode(''),
        'assets/images/gym-bag-blue-1.jpg' => base64_decode(''),
        'assets/images/gym-bag-blue-2.jpg' => base64_decode(''),
        'assets/images/gym-bag-blue-3.jpg' => base64_decode(''),
        'assets/images/barbell-pad-blue-1.jpg' => base64_decode(''),
        'assets/images/barbell-pad-blue-2.jpg' => base64_decode(''),
        'assets/images/barbell-pad-blue-3.jpg' => base64_decode(''),
        'assets/images/speed-ball-gold-1.jpg' => base64_decode(''),
        'assets/images/speed-ball-gold-2.jpg' => base64_decode(''),
        'assets/images/speed-ball-gold-3.jpg' => base64_decode(''),
        'assets/images/wrist-bandage-gold-1.jpg' => base64_decode(''),
        'assets/images/wrist-bandage-gold-2.jpg' => base64_decode(''),
        'assets/images/wrist-bandage-gold-3.jpg' => base64_decode(''),
        'assets/images/speed-ball-red-1.jpg' => base64_decode(''),
        'assets/images/speed-ball-red-2.jpg' => base64_decode(''),
        'assets/images/speed-ball-red-3.jpg' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v23']) && $_GET['nesports_apply_v23'] === '1') {
        $res = run_nesports_v23_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_v23_update();
});
